Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:bold">Line integral explorer</span>
<span id="demoNarration" style="display:block;font-size:10px;line-height:1.35;max-width:260px">Panel (a) shows a short downward-oriented segment at x = -π/2. Move t along the segment and notice that the field vectors point mostly downward there, matching the curve's orientation.</span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 4</span> <button onclick="nextStep()">▶</button></span>
<label><input id="pathPanelInput" type="checkbox" onchange="toggle_pathPanel(this.checked)"> Path: Panel (b) parabolic arc</label>
<label>Parameter t along C: <output id="pathParameterVal">0</output><input id="pathParameterInput" type="range" min="0" max="1" step="0.01" value="0" oninput="document.getElementById('pathParameterVal').value=this.value;update_pathParameter(+this.value)"></label>
<span style="font-size:10px;line-height:1.3">Drag the red endpoint handles to reshape the oriented curve.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 700);

var activePanel = 'a';
var currentT = 0;
var currentStep = 0;
var dragTarget = null;

var plotBox = { left: 55, top: 90, width: 480, height: 480 };
var domains = {
  a: { x: [-3.35, 2.1], y: [-1.0, 3.0] },
  b: { x: [-2.2, 3.2], y: [-0.7, 4.8] }
};

var panelA = {
  p0: { x: -Math.PI / 2, y: 2 },
  p1: { x: -Math.PI / 2, y: 1 }
};

var panelB = {
  p0: { x: -1, y: 1 },
  c: { x: 0.5, y: -2 },
  p1: { x: 2, y: 4 }
};

var demoSteps = [
  {
    title: 'Start with the vertical path',
    narration: 'Panel (a) shows a short downward-oriented segment at x = -π/2. Move t along the segment and notice that the field vectors point mostly downward there, matching the curve’s orientation.',
    state: { pathPanel: 'Panel (a): vertical segment', pathParameter: 0 }
  },
  {
    title: 'Track the local contribution',
    narration: 'As the point moves along C, the displayed tangent and field vector show the quantity being integrated: F(r(t)) · r′(t). Where the two arrows point in similar directions, the contribution is positive.',
    state: { pathPanel: 'Panel (a): vertical segment', pathParameter: 0.5 }
  },
  {
    title: 'Compare the curved path',
    narration: 'Switch to panel (b): the path is longer and its tangent direction changes continuously. The line integral now accumulates changing local contributions along the parabola.',
    state: { pathPanel: 'Panel (b): parabolic arc', pathParameter: 0.5 }
  },
  {
    title: 'Reshape the path',
    narration: 'Drag the endpoints to alter C and watch the integral update. The value changes because the curve now samples different x-values and tangent directions in the same vector field.',
    state: { pathPanel: 'Panel (b): parabolic arc', pathParameter: 1 }
  }
];

function domain() {
  return domains[activePanel];
}

function worldToSvg(p) {
  var d = domain();
  return {
    x: plotBox.left + (p.x - d.x[0]) / (d.x[1] - d.x[0]) * plotBox.width,
    y: plotBox.top + (d.y[1] - p.y) / (d.y[1] - d.y[0]) * plotBox.height
  };
}

function svgToWorld(p) {
  var d = domain();
  return {
    x: d.x[0] + (p.x - plotBox.left) / plotBox.width * (d.x[1] - d.x[0]),
    y: d.y[1] - (p.y - plotBox.top) / plotBox.height * (d.y[1] - d.y[0])
  };
}

function clampWorld(p) {
  var d = domain();
  return {
    x: Math.max(d.x[0], Math.min(d.x[1], p.x)),
    y: Math.max(d.y[0], Math.min(d.y[1], p.y))
  };
}

function fieldAt(p) {
  return { x: Math.cos(p.x), y: Math.sin(p.x) };
}

function activeCurve() {
  return activePanel === 'a' ? panelA : panelB;
}

function pointAt(t) {
  var c = activeCurve();
  if (activePanel === 'a') {
    return {
      x: c.p0.x + (c.p1.x - c.p0.x) * t,
      y: c.p0.y + (c.p1.y - c.p0.y) * t
    };
  }
  var u = 1 - t;
  return {
    x: u * u * c.p0.x + 2 * u * t * c.c.x + t * t * c.p1.x,
    y: u * u * c.p0.y + 2 * u * t * c.c.y + t * t * c.p1.y
  };
}

function derivAt(t) {
  var c = activeCurve();
  if (activePanel === 'a') {
    return { x: c.p1.x - c.p0.x, y: c.p1.y - c.p0.y };
  }
  return {
    x: 2 * (1 - t) * (c.c.x - c.p0.x) + 2 * t * (c.p1.x - c.c.x),
    y: 2 * (1 - t) * (c.c.y - c.p0.y) + 2 * t * (c.p1.y - c.c.y)
  };
}

function integrand(t) {
  var p = pointAt(t);
  var r = derivAt(t);
  var f = fieldAt(p);
  return f.x * r.x + f.y * r.y;
}

function integralTo(t) {
  if (t <= 0) return 0;
  return integrateSimpson(integrand, 0, t, 160);
}

function makeMarker(color, size) {
  var m = draw.marker(size, size, function (add) {
    add.path('M 0 0 L ' + size + ' ' + (size / 2) + ' L 0 ' + size + ' z').fill(color);
  });
  m.ref(size - 1, size / 2).orient('auto').markerUnits('strokeWidth');
  return m;
}

function haloText(txt, x, y, size, italic) {
  return draw.text(txt)
    .font({ family: 'Times New Roman, serif', size: size, anchor: 'middle' })
    .attr({
      fill: '#222',
      'font-style': italic ? 'italic' : 'normal',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    })
    .center(x, y);
}

function smallLabel(txt, x, y, color) {
  return draw.text(txt)
    .font({ family: 'Arial, sans-serif', size: 13, anchor: 'middle' })
    .attr({
      fill: color || '#222',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 3,
      'stroke-linejoin': 'round'
    })
    .center(x, y);
}

function fractionMinusPiOver2(x, y) {
  var g = draw.group();
  g.text('−π').font({ family: 'Times New Roman, serif', size: 32, anchor: 'middle' })
    .attr({ fill: '#222', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4 })
    .center(x, y - 13);
  g.line(x - 23, y + 5, x + 23, y + 5).stroke({ color: '#222', width: 2 });
  g.text('2').font({ family: 'Times New Roman, serif', size: 32, anchor: 'middle' })
    .attr({ fill: '#222', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4 })
    .center(x, y + 28);
  return g;
}

function drawAxes(axisMarker) {
  var d = domain();
  var x0 = worldToSvg({ x: 0, y: 0 }).x;
  var y0 = worldToSvg({ x: 0, y: 0 }).y;

  draw.line(plotBox.left - 25, y0, plotBox.left + plotBox.width + 45, y0)
    .stroke({ color: '#222', width: 3 })
    .marker('end', axisMarker);
  draw.line(x0, plotBox.top + plotBox.height + 28, x0, plotBox.top - 48)
    .stroke({ color: '#222', width: 3 })
    .marker('end', axisMarker);

  haloText('x', plotBox.left + plotBox.width + 40, y0 - 22, 35, true);
  haloText('y', x0 + 30, plotBox.top - 38, 35, true);

  var xTicks = activePanel === 'a' ? [-Math.PI / 2] : [-2, -1, 1, 2, 3];
  for (var i = 0; i < xTicks.length; i++) {
    var xs = worldToSvg({ x: xTicks[i], y: 0 }).x;
    draw.line(xs, y0 - 14, xs, y0 + 14).stroke({ color: '#222', width: 2.2 });
    if (activePanel === 'a') {
      fractionMinusPiOver2(xs, y0 + 39);
    } else {
      haloText(String(xTicks[i]).replace('-', '−'), xs, y0 + 31, 32, false);
    }
  }

  var yTicks = activePanel === 'a' ? [1, 2] : [1, 2, 3, 4];
  for (var j = 0; j < yTicks.length; j++) {
    var ys = worldToSvg({ x: 0, y: yTicks[j] }).y;
    draw.line(x0 - 12, ys, x0 + 22, ys).stroke({ color: '#222', width: 2.2 });
    haloText(String(yTicks[j]), x0 - 30, ys, 32, false);
  }
}

function drawVectorField(fieldMarker) {
  var d = domain();
  var cols = activePanel === 'a' ? 12 : 13;
  var rows = activePanel === 'a' ? 12 : 14;
  var len = activePanel === 'a' ? 30 : 27;
  var sx = plotBox.width / (d.x[1] - d.x[0]);
  var sy = plotBox.height / (d.y[1] - d.y[0]);
  var g = draw.group();

  for (var i = 0; i < cols; i++) {
    var x = d.x[0] + (i + 0.55) / cols * (d.x[1] - d.x[0]);
    for (var j = 0; j < rows; j++) {
      var y = d.y[0] + (j + 0.55) / rows * (d.y[1] - d.y[0]);
      var f = fieldAt({ x: x, y: y });
      var dx = f.x * sx;
      var dy = -f.y * sy;
      var mag = Math.sqrt(dx * dx + dy * dy) || 1;
      dx = dx / mag * len;
      dy = dy / mag * len;
      var s = worldToSvg({ x: x, y: y });
      g.line(s.x - dx * 0.45, s.y - dy * 0.45, s.x + dx * 0.45, s.y + dy * 0.45)
        .stroke({ color: '#222', width: 2.1, linecap: 'round' })
        .marker('end', fieldMarker);
    }
  }
}

function drawPath(redMarker) {
  var c = activeCurve();
  var p0s = worldToSvg(c.p0);
  var p1s = worldToSvg(c.p1);
  var pathEl;

  if (activePanel === 'a') {
    pathEl = draw.line(p0s.x, p0s.y, p1s.x, p1s.y)
      .stroke({ color: '#ff2a2a', width: 6, linecap: 'round' });
    var mid0 = worldToSvg(pointAt(0.42));
    var mid1 = worldToSvg(pointAt(0.58));
    draw.line(mid0.x, mid0.y, mid1.x, mid1.y)
      .stroke({ color: '#ff7777', width: 5, linecap: 'round' })
      .marker('end', redMarker);
    haloText('C', p0s.x + 32, (p0s.y + p1s.y) / 2 + 10, 36, true);
  } else {
    var cs = worldToSvg(c.c);
    pathEl = draw.path('M ' + p0s.x + ' ' + p0s.y + ' Q ' + cs.x + ' ' + cs.y + ' ' + p1s.x + ' ' + p1s.y)
      .fill('none')
      .stroke({ color: '#ff2a2a', width: 6, linecap: 'round', linejoin: 'round' });

    var a0 = worldToSvg(pointAt(0.18)), a1 = worldToSvg(pointAt(0.28));
    var b0 = worldToSvg(pointAt(0.48)), b1 = worldToSvg(pointAt(0.58));
    draw.line(a0.x, a0.y, a1.x, a1.y).stroke({ color: '#ff7777', width: 5, linecap: 'round' }).marker('end', redMarker);
    draw.line(b0.x, b0.y, b1.x, b1.y).stroke({ color: '#ff7777', width: 5, linecap: 'round' }).marker('end', redMarker);
    haloText('C', p1s.x + 18, p1s.y + 55, 36, true);
  }

  makeInteractive(pathEl, 'Oriented curve C', 'Oriented curve C', 'The curve is not just a set of points: its direction determines the sign of the tangent vector r′(t), and therefore the sign of each dot product contribution.');

  drawHandle(c.p0, 'p0');
  drawHandle(c.p1, 'p1');
}

function drawHandle(p, which) {
  var s = worldToSvg(p);
  var h = draw.circle(17).center(s.x, s.y).fill('#ff2a2a').stroke({ color: '#ff2a2a', width: 2 });
  h.css('cursor', 'grab');
  h.on('pointerdown', function (e) {
    dragTarget = which;
    h.css('cursor', 'grabbing');
    e.preventDefault();
  });
  h.on('mousemove', function (e) {
    showTooltip(which === 'p0' ? 'Start point of the orientation' : 'End point of the orientation', e);
  }).on('mouseleave', function () { hideTooltip(); });
  h.on('click', function () {
    showPopup('Endpoint handle', 'Drag this point to reshape C. The integral updates because the curve samples the vector field at different positions and with different tangent directions.');
  });
}

function drawLocalVectors(fieldMarker, tangentMarker) {
  var p = pointAt(currentT);
  var r = derivAt(currentT);
  var f = fieldAt(p);
  var ps = worldToSvg(p);

  var d = domain();
  var sx = plotBox.width / (d.x[1] - d.x[0]);
  var sy = plotBox.height / (d.y[1] - d.y[0]);

  function scaledVector(v, targetLen) {
    var dx = v.x * sx;
    var dy = -v.y * sy;
    var m = Math.sqrt(dx * dx + dy * dy) || 1;
    return { dx: dx / m * targetLen, dy: dy / m * targetLen };
  }

  var fv = scaledVector(f, 48);
  var tv = scaledVector(r, 54);

  var fl = draw.line(ps.x, ps.y, ps.x + fv.dx, ps.y + fv.dy)
    .stroke({ color: '#1f77b4', width: 4, linecap: 'round' })
    .marker('end', fieldMarker);
  makeInteractive(fl, 'Field vector F(r(t))', 'Local field vector', 'This arrow shows F evaluated at the moving point on C. Its alignment with the tangent determines the local contribution to the line integral.');

  var tl = draw.line(ps.x, ps.y, ps.x + tv.dx, ps.y + tv.dy)
    .stroke({ color: '#188a3b', width: 4, linecap: 'round' })
    .marker('end', tangentMarker);
  makeInteractive(tl, 'Tangent vector r′(t)', 'Local tangent vector', 'This arrow points in the orientation of the curve. Reversing the path would reverse this tangent and change the sign of the integral.');

  draw.circle(13).center(ps.x, ps.y).fill('#ffd34d').stroke({ color: '#222', width: 2 });

  smallLabel('F', ps.x + fv.dx + 12, ps.y + fv.dy - 8, '#1f77b4');
  smallLabel("r′", ps.x + tv.dx + 14, ps.y + tv.dy + 10, '#188a3b');
}

function drawReadout() {
  var dot = integrand(currentT);
  var partial = integralTo(currentT);
  var total = integralTo(1);

  var x = plotBox.left + plotBox.width - 210;
  var y = plotBox.top + 12;
  draw.rect(200, 87).move(x, y).radius(8).fill({ color: '#fff', opacity: 0.86 }).stroke({ color: '#cfd8d0', width: 1 });
  draw.text('t = ' + currentT.toFixed(2))
    .font({ family: 'Arial, sans-serif', size: 14 })
    .move(x + 12, y + 10)
    .fill('#222');
  draw.text("F(r(t)) · r′(t) = " + dot.toFixed(3))
    .font({ family: 'Arial, sans-serif', size: 14 })
    .move(x + 12, y + 32)
    .fill(dot >= 0 ? '#188a3b' : '#b00020');
  draw.text('accumulated = ' + partial.toFixed(3))
    .font({ family: 'Arial, sans-serif', size: 14 })
    .move(x + 12, y + 54)
    .fill('#222');
  draw.text('total ∫C F·dr = ' + total.toFixed(3))
    .font({ family: 'Arial, sans-serif', size: 14 })
    .move(x + 12, y + 72)
    .fill('#222');
}

function makeInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function render() {
  draw.clear();

  var axisMarker = makeMarker('#222', 12);
  var fieldMarker = makeMarker('#222', 8);
  var redMarker = makeMarker('#ff7777', 12);
  var blueMarker = makeMarker('#1f77b4', 11);
  var greenMarker = makeMarker('#188a3b', 11);

  draw.rect(plotBox.width, plotBox.height)
    .move(plotBox.left, plotBox.top)
    .fill('#e3f1e6');

  haloText('Vectors not to scale', 300, 34, 36, true);

  drawVectorField(fieldMarker);
  drawAxes(axisMarker);
  drawPath(redMarker);
  drawLocalVectors(blueMarker, greenMarker);
  drawReadout();

  haloText(activePanel === 'a' ? '(a)' : '(b)', 300, 647, 38, true);
}

function update_pathParameter(v) {
  currentT = Math.max(0, Math.min(1, v));
  render();
}

function toggle_pathPanel(on) {
  activePanel = on ? 'b' : 'a';
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];

  activePanel = step.state.pathPanel.indexOf('(b)') >= 0 ? 'b' : 'a';
  currentT = step.state.pathParameter;

  var chk = document.getElementById('pathPanelInput');
  if (chk) chk.checked = activePanel === 'b';

  var slider = document.getElementById('pathParameterInput');
  var out = document.getElementById('pathParameterVal');
  if (slider) slider.value = String(currentT);
  if (out) out.value = String(currentT);

  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (lab) lab.textContent = (currentStep + 1) + ' / ' + demoSteps.length;

  render();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

function clientToSvg(e) {
  var pt = draw.node.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  var ctm = draw.node.getScreenCTM();
  if (!ctm) return null;
  return pt.matrixTransform(ctm.inverse());
}

document.addEventListener('pointermove', function (e) {
  if (!dragTarget) return;
  var sp = clientToSvg(e);
  if (!sp) return;
  var wp = clampWorld(svgToWorld(sp));
  var c = activeCurve();
  c[dragTarget].x = wp.x;
  c[dragTarget].y = wp.y;
  render();
});

document.addEventListener('pointerup', function () {
  dragTarget = null;
});

window.update_pathParameter = update_pathParameter;
window.toggle_pathPanel = toggle_pathPanel;
window.nextStep = nextStep;
window.prevStep = prevStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

