// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 1450);

var activePanel = 'a';
var currentT = 0;
var currentStep = 0;
var showLocal = false;
var dragTarget = null;
var didDrag = false;

var panels = {
  a: {
    key: 'a',
    box: { left: 42, top: 120, width: 515, height: 515 },
    domain: { x: [-2.2, 1.35], y: [-1.0, 3.0] },
    labelY: 724
  },
  b: {
    key: 'b',
    box: { left: 42, top: 835, width: 515, height: 515 },
    domain: { x: [-2.2, 3.2], y: [-0.8, 4.8] },
    labelY: 1420
  }
};

var curves = {
  a: {
    type: 'line',
    p0: { x: -Math.PI / 2, y: 2 },
    p1: { x: -Math.PI / 2, y: 1 }
  },
  b: {
    type: 'quad',
    p0: { x: -1, y: 1 },
    c: { x: 0.5, y: -2 },
    p1: { x: 2, y: 4 }
  }
};

var demoSteps = [
  {
    narration: 'Panel (a) shows a short downward-oriented segment at x = −π/2. Move t along the segment and notice that the field vectors point mostly downward there, matching the curve’s orientation.',
    state: { pathPanel: 'a', pathParameter: 0, showLocal: false }
  },
  {
    narration: 'As the point moves along C, the displayed tangent and field vector show the quantity being integrated: F(r(t)) · r′(t). Similar directions give a positive contribution.',
    state: { pathPanel: 'a', pathParameter: 0.5, showLocal: true }
  },
  {
    narration: 'Switch to panel (b): the path is longer and its tangent direction changes continuously. The line integral now accumulates changing local contributions along the parabola.',
    state: { pathPanel: 'b', pathParameter: 0.5, showLocal: true }
  },
  {
    narration: 'Drag the red endpoints to alter C and watch the readout update. The value changes because the curve samples different field vectors with different tangent directions.',
    state: { pathPanel: 'b', pathParameter: 1, showLocal: true }
  }
];

function panelWorldToSvg(panelKey, p) {
  var pan = panels[panelKey];
  var b = pan.box;
  var d = pan.domain;
  return {
    x: b.left + (p.x - d.x[0]) / (d.x[1] - d.x[0]) * b.width,
    y: b.top + (d.y[1] - p.y) / (d.y[1] - d.y[0]) * b.height
  };
}

function svgToPanelWorld(panelKey, p) {
  var pan = panels[panelKey];
  var b = pan.box;
  var d = pan.domain;
  return {
    x: d.x[0] + (p.x - b.left) / b.width * (d.x[1] - d.x[0]),
    y: d.y[1] - (p.y - b.top) / b.height * (d.y[1] - d.y[0])
  };
}

function clampToPanel(panelKey, p) {
  var d = panels[panelKey].domain;
  return {
    x: Math.max(d.x[0], Math.min(d.x[1], p.x)),
    y: Math.max(d.y[0], Math.min(d.y[1], p.y))
  };
}

function fieldAt(p) {
  return { x: Math.cos(p.x), y: Math.sin(p.x) };
}

function pointAt(panelKey, t) {
  var c = curves[panelKey];
  if (c.type === 'line') {
    return {
      x: c.p0.x + (c.p1.x - c.p0.x) * t,
      y: c.p0.y + (c.p1.y - c.p0.y) * t
    };
  }
  var u = 1 - t;
  return {
    x: u * u * c.p0.x + 2 * u * t * c.c.x + t * t * c.p1.x,
    y: u * u * c.p0.y + 2 * u * t * c.c.y + t * t * c.p1.y
  };
}

function derivAt(panelKey, t) {
  var c = curves[panelKey];
  if (c.type === 'line') {
    return { x: c.p1.x - c.p0.x, y: c.p1.y - c.p0.y };
  }
  return {
    x: 2 * (1 - t) * (c.c.x - c.p0.x) + 2 * t * (c.p1.x - c.c.x),
    y: 2 * (1 - t) * (c.c.y - c.p0.y) + 2 * t * (c.p1.y - c.c.y)
  };
}

function integrand(panelKey, t) {
  var p = pointAt(panelKey, t);
  var r = derivAt(panelKey, t);
  var f = fieldAt(p);
  return f.x * r.x + f.y * r.y;
}

function integralTo(panelKey, t) {
  if (t <= 0) return 0;
  return integrateSimpson(function (u) { return integrand(panelKey, u); }, 0, t, 180);
}

function makeMarker(color, size) {
  var m = draw.marker(size, size, function (add) {
    add.path('M 0 0 L ' + size + ' ' + (size / 2) + ' L 0 ' + size + ' z')
      .fill(color)
      .stroke('none');
  });
  m.ref(size, size / 2);
  m.orient('auto');
  return m;
}

function haloText(txt, x, y, size, italic, anchor) {
  return draw.text(txt)
    .font({ family: 'Times New Roman, Times, serif', size: size, anchor: anchor || 'middle' })
    .attr({
      fill: '#222',
      'font-style': italic ? 'italic' : 'normal',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    })
    .center(x, y);
}

function sansText(txt, x, y, size, color, anchor) {
  return draw.text(txt)
    .font({ family: 'Arial, sans-serif', size: size, anchor: anchor || 'start' })
    .attr({
      fill: color || '#222',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 3,
      'stroke-linejoin': 'round'
    })
    .move(x, y);
}

function fractionMinusPiOver2(x, y) {
  var g = draw.group();
  g.text('−π')
    .font({ family: 'Times New Roman, Times, serif', size: 34, anchor: 'middle' })
    .attr({ fill: '#222', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .center(x, y - 14);
  g.line(x - 26, y + 7, x + 26, y + 7).stroke({ color: '#222', width: 2.2 });
  g.text('2')
    .font({ family: 'Times New Roman, Times, serif', size: 34, anchor: 'middle' })
    .attr({ fill: '#222', 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .center(x, y + 31);
  return g;
}

function makeInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      if (!didDrag) showPopup(title, body);
    });
}

function drawAxes(panelKey, axisMarker) {
  var pan = panels[panelKey];
  var b = pan.box;
  var x0 = panelWorldToSvg(panelKey, { x: 0, y: 0 }).x;
  var y0 = panelWorldToSvg(panelKey, { x: 0, y: 0 }).y;

  draw.line(b.left - 28, y0, b.left + b.width + 48, y0)
    .stroke({ color: '#222', width: 3, linecap: 'square' })
    .marker('end', axisMarker);
  draw.line(x0, b.top + b.height + 30, x0, b.top - 50)
    .stroke({ color: '#222', width: 3, linecap: 'square' })
    .marker('end', axisMarker);

  haloText('x', b.left + b.width + 39, y0 - 31, 38, true);
  haloText('y', x0 + 33, b.top - 36, 38, true);

  if (panelKey === 'a') {
    var xs = panelWorldToSvg(panelKey, { x: -Math.PI / 2, y: 0 }).x;
    draw.line(xs, y0 - 17, xs, y0 + 17).stroke({ color: '#222', width: 2.2 });
    fractionMinusPiOver2(xs, y0 + 49);

    [1, 2].forEach(function (v) {
      var ys = panelWorldToSvg(panelKey, { x: 0, y: v }).y;
      draw.line(x0 - 10, ys, x0 + 21, ys).stroke({ color: '#222', width: 2.2 });
      haloText(String(v), x0 - 28, ys, 35, false);
    });
  } else {
    [-2, -1, 1, 2, 3].forEach(function (v) {
      var xs2 = panelWorldToSvg(panelKey, { x: v, y: 0 }).x;
      draw.line(xs2, y0 - 18, xs2, y0 + 18).stroke({ color: '#222', width: 2.2 });
      haloText(String(v).replace('-', '−'), xs2, y0 + 32, 35, false);
    });

    [1, 2, 3, 4].forEach(function (v) {
      var ys2 = panelWorldToSvg(panelKey, { x: 0, y: v }).y;
      draw.line(x0 - 9, ys2, x0 + 22, ys2).stroke({ color: '#222', width: 2.2 });
      haloText(String(v), x0 - 28, ys2, 35, false);
    });
  }
}

function drawVectorField(panelKey, fieldMarker) {
  var pan = panels[panelKey];
  var b = pan.box;
  var d = pan.domain;
  var cols = panelKey === 'a' ? 13 : 14;
  var rows = panelKey === 'a' ? 13 : 15;
  var len = panelKey === 'a' ? 31 : 27;
  var sx = b.width / (d.x[1] - d.x[0]);
  var sy = b.height / (d.y[1] - d.y[0]);
  var g = draw.group();

  for (var i = 0; i < cols; i++) {
    var x = d.x[0] + (i + 0.5) / cols * (d.x[1] - d.x[0]);
    for (var j = 0; j < rows; j++) {
      var y = d.y[0] + (j + 0.5) / rows * (d.y[1] - d.y[0]);
      var f = fieldAt({ x: x, y: y });
      var dx = f.x * sx;
      var dy = -f.y * sy;
      var mag = Math.sqrt(dx * dx + dy * dy) || 1;
      dx = dx / mag * len;
      dy = dy / mag * len;
      var s = panelWorldToSvg(panelKey, { x: x, y: y });
      g.line(s.x - dx * 0.42, s.y - dy * 0.42, s.x + dx * 0.42, s.y + dy * 0.42)
        .stroke({ color: '#222', width: 2, linecap: 'round' })
        .marker('end', fieldMarker);
    }
  }
}

function curvePathString(panelKey) {
  var c = curves[panelKey];
  var p0 = panelWorldToSvg(panelKey, c.p0);
  var p1 = panelWorldToSvg(panelKey, c.p1);
  if (c.type === 'line') {
    return 'M ' + p0.x + ' ' + p0.y + ' L ' + p1.x + ' ' + p1.y;
  }
  var cp = panelWorldToSvg(panelKey, c.c);
  return 'M ' + p0.x + ' ' + p0.y + ' Q ' + cp.x + ' ' + cp.y + ' ' + p1.x + ' ' + p1.y;
}

function drawDirectionArrow(panelKey, t0, t1, redMarker) {
  var a = panelWorldToSvg(panelKey, pointAt(panelKey, t0));
  var b = panelWorldToSvg(panelKey, pointAt(panelKey, t1));
  draw.line(a.x, a.y, b.x, b.y)
    .stroke({ color: '#ff5a5a', width: 6, opacity: 0.78, linecap: 'round' })
    .marker('end', redMarker);
}

function drawEndpoint(panelKey, which) {
  var c = curves[panelKey];
  var p = c[which];
  var s = panelWorldToSvg(panelKey, p);
  var dot = draw.circle(20).center(s.x, s.y)
    .fill('#ff2424')
    .stroke({ color: '#ff2424', width: 1.5 });
  dot.css('cursor', 'grab');
  dot.on('pointerdown', function (e) {
    activePanel = panelKey;
    dragTarget = { panel: panelKey, which: which };
    didDrag = false;
    dot.css('cursor', 'grabbing');
    e.preventDefault();
  });
  dot.on('mousemove', function (e) {
    showTooltip(which === 'p0' ? 'Start point of the oriented curve' : 'End point of the oriented curve', e);
  }).on('mouseleave', function () { hideTooltip(); });
  dot.on('click', function () {
    if (!didDrag) {
      showPopup('Endpoint of C', 'This red point is an endpoint of the oriented curve. Dragging it changes the path, so the line integral samples the vector field along a different curve.');
    }
  });
}

function drawCurve(panelKey, redMarker) {
  var c = curves[panelKey];
  var path = draw.path(curvePathString(panelKey))
    .fill('none')
    .stroke({ color: '#ff2424', width: 6, linecap: 'round', linejoin: 'round' });

  makeInteractive(
    path,
    'Oriented curve C',
    'Oriented curve C',
    'The red arrows indicate the direction of travel. The tangent r′(t) follows this orientation, so reversing the path would reverse the sign of every dot product contribution.'
  );

  if (panelKey === 'a') {
    drawDirectionArrow(panelKey, 0.30, 0.58, redMarker);
    var mid = panelWorldToSvg(panelKey, pointAt(panelKey, 0.55));
    haloText('C', mid.x + 31, mid.y + 14, 42, true);
  } else {
    drawDirectionArrow(panelKey, 0.12, 0.24, redMarker);
    drawDirectionArrow(panelKey, 0.48, 0.60, redMarker);
    var lab = panelWorldToSvg(panelKey, pointAt(panelKey, 0.82));
    haloText('C', lab.x + 35, lab.y + 18, 42, true);
  }

  drawEndpoint(panelKey, 'p0');
  drawEndpoint(panelKey, 'p1');
}

function drawLocalVectors(fieldMarker, tangentMarker) {
  if (!showLocal) return;

  var panelKey = activePanel;
  var pan = panels[panelKey];
  var b = pan.box;
  var d = pan.domain;
  var p = pointAt(panelKey, currentT);
  var r = derivAt(panelKey, currentT);
  var f = fieldAt(p);
  var ps = panelWorldToSvg(panelKey, p);
  var sx = b.width / (d.x[1] - d.x[0]);
  var sy = b.height / (d.y[1] - d.y[0]);

  function scaled(v, len) {
    var dx = v.x * sx;
    var dy = -v.y * sy;
    var m = Math.sqrt(dx * dx + dy * dy) || 1;
    return { dx: dx / m * len, dy: dy / m * len };
  }

  var fv = scaled(f, 48);
  var tv = scaled(r, 55);

  var fl = draw.line(ps.x, ps.y, ps.x + fv.dx, ps.y + fv.dy)
    .stroke({ color: '#1f77b4', width: 4, linecap: 'round' })
    .marker('end', fieldMarker);
  makeInteractive(fl, 'Field vector F(r(t))', 'Local field vector', 'This blue arrow is the vector field evaluated at the moving point on C. Its alignment with the tangent determines the sign and size of the local contribution.');

  var tl = draw.line(ps.x, ps.y, ps.x + tv.dx, ps.y + tv.dy)
    .stroke({ color: '#188a3b', width: 4, linecap: 'round' })
    .marker('end', tangentMarker);
  makeInteractive(tl, "Tangent vector r′(t)", 'Local tangent vector', 'This green arrow points in the oriented direction of the curve. The line integral accumulates F(r(t)) · r′(t) along the entire path.');

  draw.circle(13).center(ps.x, ps.y)
    .fill('#ffd64d')
    .stroke({ color: '#222', width: 2 });

  sansText('F', ps.x + fv.dx + 8, ps.y + fv.dy - 14, 15, '#1f77b4');
  sansText("r′", ps.x + tv.dx + 8, ps.y + tv.dy + 2, 15, '#188a3b');

  var dot = integrand(panelKey, currentT);
  var partial = integralTo(panelKey, currentT);
  var total = integralTo(panelKey, 1);
  var rx = b.left + b.width - 205;
  var ry = b.top + 13;
  if (panelKey === 'b') {
    rx = b.left + 13;
    ry = b.top + 13;
  }

  var card = draw.group();
  card.rect(192, 88).move(rx, ry).radius(7)
    .fill({ color: '#fff', opacity: 0.88 })
    .stroke({ color: '#bfc8bf', width: 1 });
  card.text('active panel: (' + panelKey + ')')
    .font({ family: 'Arial, sans-serif', size: 13 })
    .fill('#222')
    .move(rx + 10, ry + 8);
  card.text('t = ' + currentT.toFixed(2))
    .font({ family: 'Arial, sans-serif', size: 13 })
    .fill('#222')
    .move(rx + 10, ry + 27);
  card.text("F(r(t)) · r′(t) = " + dot.toFixed(3))
    .font({ family: 'Arial, sans-serif', size: 13 })
    .fill(dot >= 0 ? '#188a3b' : '#b00020')
    .move(rx + 10, ry + 46);
  card.text('∫₀ᵗ F·dr = ' + partial.toFixed(3))
    .font({ family: 'Arial, sans-serif', size: 13 })
    .fill('#222')
    .move(rx + 10, ry + 65);
}

function drawPanel(panelKey, axisMarker, fieldMarker, redMarker) {
  var pan = panels[panelKey];
  var b = pan.box;

  draw.rect(b.width, b.height)
    .move(b.left, b.top)
    .fill('#e4f2e8')
    .stroke('none');

  drawVectorField(panelKey, fieldMarker);
  drawAxes(panelKey, axisMarker);
  drawCurve(panelKey, redMarker);
  haloText('(' + panelKey + ')', 300, pan.labelY, 42, true);
}

function render() {
  draw.clear();

  var axisMarker = makeMarker('#222', 15);
  var fieldMarker = makeMarker('#222', 8);
  var redMarker = makeMarker('#ff5a5a', 15);
  var blueMarker = makeMarker('#1f77b4', 12);
  var greenMarker = makeMarker('#188a3b', 12);

  haloText('Vectors not to scale', 300, 38, 42, true);

  drawPanel('a', axisMarker, fieldMarker, redMarker);
  drawPanel('b', axisMarker, fieldMarker, redMarker);
  drawLocalVectors(blueMarker, greenMarker);
}

function update_pathParameter(v) {
  currentT = Math.max(0, Math.min(1, v));
  showLocal = true;
  render();
}

function toggle_pathPanel(on) {
  activePanel = on ? 'b' : 'a';
  showLocal = true;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];

  activePanel = step.state.pathPanel;
  currentT = step.state.pathParameter;
  showLocal = step.state.showLocal;

  var chk = document.getElementById('pathPanelInput');
  if (chk) chk.checked = activePanel === 'b';

  var slider = document.getElementById('pathParameterInput');
  var out = document.getElementById('pathParameterVal');
  if (slider) slider.value = String(currentT);
  if (out) out.value = String(currentT);

  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (lab) lab.textContent = (currentStep + 1) + ' / ' + demoSteps.length;

  render();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

function clientToSvg(e) {
  var pt = draw.node.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  var ctm = draw.node.getScreenCTM();
  if (!ctm) return null;
  return pt.matrixTransform(ctm.inverse());
}

document.addEventListener('pointermove', function (e) {
  if (!dragTarget) return;
  var sp = clientToSvg(e);
  if (!sp) return;
  var wp = clampToPanel(dragTarget.panel, svgToPanelWorld(dragTarget.panel, sp));
  curves[dragTarget.panel][dragTarget.which].x = wp.x;
  curves[dragTarget.panel][dragTarget.which].y = wp.y;
